            // 2. 获取页面上所有的塔罗状态栏 (确保聊天记录中的历史状态栏也能同步)
            const wrappers = document.querySelectorAll('.tarot-wrapper');

            wrappers.forEach(wrapper => {
                // 3. 初始化应用缓存的主题
                if (savedTheme === 'light') {
                    wrapper.classList.add('theme-light');
                } else {
                    wrapper.classList.remove('theme-light');
