                        const isCurrentlyLight = wrapper.classList.contains('theme-light');
                        const newTheme = isCurrentlyLight ? 'dark' : 'light';

                        // 更新缓存
                        localStorage.setItem('tarotTheme', newTheme);

                        // 同步更新页面上所有的状态栏，保持聊天记录里的样式统一
                        const allWrappers = document.querySelectorAll('.tarot-wrapper');
                        allWrappers.forEach(w => {
