    <script>
        (function() {
            const shell = document.getElementById('status-bar-shell');
            const themeBtn = document.getElementById('st-theme-btn');
            const themeIcon = document.getElementById('st-theme-icon');
            const themeLabel = document.getElementById('st-theme-label');

            // --- 1. 天照与月读模式切换 ---
            function applyTheme(theme) {
                if (theme === 'night') {
                    shell.classList.remove('theme-day');
                    shell.classList.add('theme-night');
                    themeIcon.className = 'fas fa-moon';
                    themeLabel.textContent = 'TSUKUYOMI';
                } else {
                    shell.classList.remove('theme-night');
                    shell.classList.add('theme-day');
                    themeIcon.className = 'fas fa-sun';
                    themeLabel.textContent = 'AMATERASU';
                }
            }

            let savedTheme = 'night';
            try { savedTheme = localStorage.getItem('thismoment_statusbar_theme') || 'night'; } catch (_) {}
            applyTheme(savedTheme);

            themeBtn.addEventListener('click', function() {
                let currentTheme = shell.classList.contains('theme-night') ? 'night' : 'day';
                let nextTheme = currentTheme === 'night' ? 'day' : 'night';
                try { localStorage.setItem('thismoment_statusbar_theme', nextTheme); } catch (_) {}
                applyTheme(nextTheme);
            });

            // --- 2. 此时此刻头像适配：当前消息优先，顶部角色头像兜底 ---
            // 需要可执行脚本且能访问宿主 DOM 的 HTML 入口；不是自定义 CSS。
            (function bindThisMomentAvatar() {
                const target = document.getElementById('st-dynamic-image');
                if (!target) return;
                let lastImage = '';

                function readAvatar(node) {
                    if (!node) return '';
                    const img = node.matches('img') ? node : node.querySelector('img');
                    if (img) {
                        const src = img.getAttribute('src');
                        const srcset = img.getAttribute('srcset');
                        if ((src || srcset) && (img.currentSrc || img.src)) {
                            return `url(${JSON.stringify(img.currentSrc || img.src)})`;
                        }
                    }
                    const background = node.ownerDocument.defaultView.getComputedStyle(node).backgroundImage;
                    return background && background !== 'none' ? background : '';
                }

                function findAvatar(doc, anchor) {
                    const screen = doc.querySelector('#this-moment-screen');
                    if (!screen) return '';
                    const message = anchor && anchor.closest('.tm-para-char');
                    if (message) {
                        // 当前消息没有头像时不借用其他角色，避免历史消息或多人串图。
                        return readAvatar(message.querySelector('.tc-header .tc-avatar-img'));
                    }
                    // 排除用户切换按钮中的头像。
                    return readAvatar(screen.querySelector('.tm-top-drop-btn:not(.tm-top-drop-btn-user) .tm-header-avatar'));
                }

                function refreshAvatar() {
                    let image = findAvatar(document, target);
                    // 支持同源内嵌 HTML；跨域/沙盒访问失败时保持空唱片。
                    let host = window;
                    for (let depth = 0; !image && depth < 5; depth++) {
                        try {
                            if (host.parent === host) break;
                            const frame = host.frameElement;
                            host = host.parent;
                            image = findAvatar(host.document, frame);
                        } catch (_) {
                            break;
                        }
                    }
                    if (image !== lastImage) {
                        target.style.backgroundImage = image || 'none';
                        target.setAttribute('aria-label', image ? '角色头像' : '角色暂无头像');
                        lastImage = image;
                    }
                }

                refreshAvatar();
                // 宿主可能延迟挂载、更换 img 或更新图片 URL；定时同步也覆盖这些情况。
                const timer = window.setInterval(refreshAvatar, 1000);
                window.addEventListener('pagehide', () => window.clearInterval(timer), { once: true });
            })();
            // --- 3. Canvas 垂直雨幕物理特效 ---
            (function() {
                const canvas = document.getElementById('st-particle-canvas');
                if (!canvas) return;
                const ctx = canvas.getContext('2d');
                let w = canvas.width = canvas.parentNode.offsetWidth;
                let h = canvas.height = canvas.parentNode.offsetHeight;
                const pArr = [];

                // 初始化25根垂直下落的细灰色雨丝
                for (let i = 0; i < 25; i++) {
                    pArr.push({
                        x: Math.random() * w,
                        y: Math.random() * h,
                        l: Math.random() * 12 + 6,
                        vy: Math.random() * 3.5 + 2.5,
                        a: Math.random() * 0.28 + 0.12
                    });
                }

                function drawRain() {
                    ctx.clearRect(0, 0, w, h);
                    ctx.lineWidth = 1;

                    pArr.forEach(p => {
                        p.y += p.vy;

                        if (p.y > h) {
                            p.y = -p.l;
                            p.x = Math.random() * w;
                        }

                        ctx.beginPath();
                        ctx.strokeStyle = `rgba(180, 180, 180, ${p.a})`;
                        ctx.moveTo(p.x, p.y);
                        ctx.lineTo(p.x, p.y + p.l);
                        ctx.stroke();
                    });
                    requestAnimationFrame(drawRain);
                }

                window.addEventListener('resize', () => {
                    w = canvas.width = canvas.parentNode.offsetWidth;
                    h = canvas.height = canvas.parentNode.offsetHeight;
                });
                drawRain();
            })();

            // --- 4. 括号解构器 ---
            function extractBlocks(text) {
                text = text.replace(/^[\s\S]*<\/(?:think|thinking)>/i, '').trim();
                const blocks = [];
                let currentBlock = "";
                let depth = 0;
                for (let i = 0; i < text.length; i++) {
                    const char = text[i];
                    if (char === '[') {
                        if (depth > 0) currentBlock += char;
                        depth++;
                    } else if (char === ']') {
                        depth--;
                        if (depth === 0) {
                            if (currentBlock.trim()) blocks.push(currentBlock);
                            currentBlock = "";
                        } else if (depth > 0) {
                            currentBlock += char;
                        } else { depth = 0; }
                    } else {
                        if (depth > 0) currentBlock += char;
                    }
                }
                if (depth > 0 && currentBlock.trim()) blocks.push(currentBlock);
                return blocks;
            }

            // --- 5. 智能解析与渲染 ---
            try {
                const rawData = document.getElementById('status-raw-data').textContent;
                const blocks = extractBlocks(rawData);

                let parsed = {
                    title: '未定叙事',
                    seq: '01',
                    time: '----/--/-- 星期- --:-- --',
                    loc: '世界边缘 · 某个维度',
                    relation: 'CHAR X USER',
                    weather: '薄暮微雨',
                    quote: '世界上只有一种英雄主义。',
                    author: '罗曼·罗兰',
                    poem: '当前分歧静默，叙事齿轮待续。'
                };

                blocks.forEach(b => {
                    const parts = b.split('|').map(s => s.trim());
                    if (parts.length < 2) return;
                    const header = parts[0].toLowerCase();

                    if (header === 'title') {
                        parsed.title = parts[1] || parsed.title;
                    } else if (header === 'seq') {
                        parsed.seq = parts[1] ? 'No.' + parts[1] : parsed.seq;
                    } else if (header === 'time') {
                        parsed.time = parts[1] || parsed.time;
                    } else if (header === 'loc') {
                        parsed.loc = parts.slice(1).join(' · ');
                    } else if (header === 'relation') {
                        parsed.relation = `${parts[1]} X ${parts[2]}`;
                    } else if (header === 'weather') {
                        // 4-6 字天气强制安全截取，防溢出
                        parsed.weather = (parts[1] || parsed.weather).substring(0, 6);
                    } else if (header === 'quote') {
                        const rawQuote = (parts[1] || '').replace(/[“”"'「」]/g, '').trim();
                        const authorSplit = rawQuote.split('——');
                        if (authorSplit.length > 1) {
                            parsed.quote = authorSplit[0].trim();
                            parsed.author = '— ' + authorSplit[1].trim();
                        } else {
                            parsed.quote = rawQuote;
                            parsed.author = '';
                        }
                    } else if (header === 'poem') {
                        parsed.poem = parts.slice(1).join('\n');
                    }
                });

                // 更新 DOM 节点数据
                document.getElementById('st-render-title').textContent = parsed.title;
                document.getElementById('st-render-watermark').textContent = parsed.seq.toUpperCase();
                document.getElementById('st-render-time').textContent = parsed.time;
                document.getElementById('st-render-relation').textContent = parsed.relation;
                document.getElementById('st-render-weather').textContent = parsed.weather;
                document.getElementById('st-render-location').textContent = parsed.loc;

                // 配套序号自动计算契合的英标手写词
                const enWords = ["Nostalgia", "Requiem", "Solitude", "Melancholy", "Eternity", "Oblivion"];
                const wordIndex = parseInt(parsed.seq.replace(/\D/g, '')) || 0;
                const scriptText = enWords[wordIndex % enWords.length];
                document.getElementById('st-render-en').textContent = scriptText;
                document.getElementById('st-render-sub').textContent = "THE AFTERGLOW OF " + scriptText.toUpperCase();

                // 渲染文学摘抄
                const quoteTextNode = document.getElementById('st-render-quote');
                if (parsed.author) {
                    quoteTextNode.innerHTML = `${parsed.quote}<span class="st-hero-author">${parsed.author}</span>`;
                } else {
                    quoteTextNode.textContent = parsed.quote;
                }

                // 智能分句并两两合并（每两句断一次换行，行内以宽空格呼吸留白）
                const rawLines = parsed.poem.split(/[\n\r,，。|｜]/).map(line => line.trim()).filter(line => line.length > 0);
                const combinedLines = [];
                for (let i = 0; i < rawLines.length; i += 2) {
                    if (i + 1 < rawLines.length) {
                        combinedLines.push(`${rawLines[i]}&nbsp;&nbsp;&nbsp;${rawLines[i + 1]}`);
                    } else {
                        combinedLines.push(rawLines[i]);
                    }
                }
                const poemContainer = document.getElementById('st-render-poem');
                poemContainer.innerHTML = combinedLines.map(line => `<span class="st-poetic-line">${line}</span>`).join('');

                // 头像由此时此刻适配器独立同步。

            } catch (err) {
                console.error("状态栏解析错误: ", err);
            }
        })();
    </script>
